mapper.select:
SELECT id, event_id, change_kind, payload, status, retry_count, max_retry, next_retry_at, last_error, locked_by, locked_at, processed_at, source_module, source_biz_id, create_time, update_time, version FROM sys_authorization_invalidation_outbox WHERE status IN
#{status}
AND (next_retry_at IS NULL OR next_retry_at <= #{now}) ORDER BY create_time ASC LIMIT #{limit}

SELECT aio.id, aio.event_id, aio.change_kind, aio.status, aio.retry_count, aio.max_retry, aio.next_retry_at, aio.last_error, aio.locked_by, aio.locked_at, aio.processed_at, aio.source_module, aio.source_biz_id, aio.create_time, aio.update_time, aio.create_user, aio.update_user FROM sys_authorization_invalidation_outbox aio
AND aio.event_id = #{query.eventId}
AND aio.change_kind = #{query.changeKind}
AND aio.status = #{query.status}
AND aio.source_module = #{query.sourceModule}
AND aio.source_biz_id = #{query.sourceBizId}
AND aio.create_time >= #{query.createTimeStart}
AND aio.create_time <= #{query.createTimeEnd}
AND aio.processed_at >= #{query.processedAtStart}
AND aio.processed_at <= #{query.processedAtEnd}
ORDER BY aio.create_time DESC
